"""Execution wrapper for the candidate-generation and reference logic from the provided notebook."""
CELL2_SOURCE = '# @title 2 · Cấu hình, căn chỉnh và dựng candidate từ AB1\nPRIMER_5 = "ACACGACGCTCTTCCGATCT"  # @param {type:"string"}\nPRIMER_3 = "AGATCGGAAGAGCACACGTCT"  # @param {type:"string"}\n# Hai primer được viết theo chiều chuẩn 5′→3′ của full strand.\n# Để dùng trim tự động, giữ hai ô cửa sổ trống.\n# Với s1 cũng có thể nhập OF_WINDOW = "15:56", OR_RC_WINDOW = "22:58".\nOF_WINDOW = ""  # @param {type:"string"}\nOR_RC_WINDOW = ""  # @param {type:"string"}\nEXPECTED_REGION_NT = 0  # @param {type:"integer"}\nMIN_PAIRED_NT = 10  # @param {type:"integer"}\nMIN_OVERLAP_IDENTITY = 0.75  # @param {type:"number"}\nMIN_SINGLE_Q = 10  # @param {type:"integer"}\nTOP_K_PER_MODEL = 12  # @param {type:"integer"}\nMAX_ALIGNMENTS = 3  # @param {type:"integer"}\nMAX_ALT_CHANGES = 2  # @param {type:"integer"}\n\n# Reference được nhập sau khi chốt danh sách.\nPEAK_WEIGHT = 0.5\nPEAK_RATIO = 0.60\nALIGNMENT_SCORE_WINDOW = 4.0\nMAX_ALT_LOG_DROP = 9.0\n\nVERBOSE_QC = False  # @param {type:"boolean"}\nimport contextlib\nimport io\n\nfrom collections import defaultdict\nfrom dataclasses import dataclass\nimport math\nimport re\nimport struct\n\nimport numpy as np\nimport pandas as pd\nfrom scipy.signal import find_peaks\nfrom IPython.display import display\n\nBASES = "ACGT"\nCOMPLEMENT = str.maketrans("ACGTN", "TGCAN")\n\n@dataclass\nclass Read:\n    role: str\n    seq: str\n    q: np.ndarray\n    peaks: np.ndarray\n    trace: np.ndarray\n\ndef read_ab1(data, role, reverse=False):\n    if data[:4] != b"ABIF" or len(data) < 34:\n        raise ValueError(f"{role} không có header ABIF hợp lệ.")\n    directory = struct.Struct(">4sIHHIIII")\n    _, _, _, _, count, _, offset, _ = directory.unpack_from(data, 6)\n    if offset < 34 or count > (len(data) - offset) // directory.size:\n        raise ValueError(f"Directory ABIF của {role} không hợp lệ.")\n    tags = {}\n    for i in range(count):\n        pos = offset + i * directory.size\n        key, num, _, _, _, size, loc, _ = directory.unpack_from(data, pos)\n        start = pos + 20 if size <= 4 else loc\n        if start + size > len(data):\n            raise ValueError(f"Tag {key!r} của {role} nằm ngoài file.")\n        tags[key, num] = data[start:start+size]\n    version = 2 if (b"PBAS", 2) in tags else 1\n    try:\n        seq = tags[b"PBAS", version].decode("ascii").rstrip("\\0").upper()\n        seq = "".join(b if b in BASES else "N" for b in seq)\n        q = np.frombuffer(tags[b"PCON", version], dtype="u1").astype(int)\n        peaks = np.frombuffer(tags[b"PLOC", version], dtype=">u2").astype(int)\n        order = tags[b"FWO_", 1].decode("ascii").rstrip("\\0")\n        if len(order) != 4 or set(order) != set(BASES):\n            raise ValueError(f"Không nhận dạng được thứ tự 4 kênh của {role}.")\n        trace = np.stack([\n            np.frombuffer(tags[b"DATA", 9 + order.index(b)], dtype=">i2")\n            for b in BASES\n        ]).astype(float)\n    except (KeyError, UnicodeError) as exc:\n        raise ValueError(f"{role} thiếu base-call, Phred, PLOC hoặc trace đã xử lý: {exc}") from exc\n    if not seq or len(seq) != len(q) or len(seq) != len(peaks):\n        raise ValueError(f"PBAS, PCON và PLOC của {role} phải có cùng số base.")\n    if not trace.shape[1] or peaks[-1] >= trace.shape[1] or np.any(np.diff(peaks) <= 0):\n        raise ValueError(f"PLOC không hợp lệ trong {role}.")\n    if reverse:\n        seq = seq.translate(COMPLEMENT)[::-1]\n        q = q[::-1]\n        peaks = trace.shape[1] - 1 - peaks[::-1]\n        trace = trace[::-1, ::-1]\n    return Read(role, seq, q, peaks, trace)\n\ndef primer_hit(seq, motif, side):\n    if len(seq) < len(motif):\n        return None\n    last = len(seq) - len(motif)\n    edge = min(32, last)\n    positions = range(edge+1) if side == "left" else range(last-edge, last+1)\n    options = [\n        (sum(x != y for x, y in zip(seq[i:i+len(motif)], motif)),\n         i if side == "left" else last-i, i)\n        for i in positions\n    ]\n    errors, _, start = min(options)\n    return (start, start + len(motif), errors) if errors <= 2 else None\n\ndef trim_read(read, manual, primer_5, primer_3):\n    left = primer_hit(read.seq, primer_5, "left")\n    right = primer_hit(read.seq, primer_3, "right")\n    lo, hi = (left[1] if left else 0), (right[0] if right else len(read.seq))\n    if hi <= lo:\n        raise ValueError(f"Hai motif vùng mồi chồng nhau trên {read.role}. Kiểm tra primer.")\n    if manual.strip():\n        parsed = re.fullmatch(r"\\s*(\\d+)\\s*:\\s*(\\d+)\\s*", manual)\n        if not parsed:\n            raise ValueError(f"Cửa sổ của {read.role} cần có dạng 15:56.")\n        start, end = map(int, parsed.groups())\n        if not lo <= start-1 < end <= hi:\n            raise ValueError(f"Cửa sổ của {read.role} phải nằm trong vùng {lo+1}–{hi}.")\n        start -= 1\n    else:\n        good = (read.q[lo:hi] >= MIN_SINGLE_Q) & (np.array(list(read.seq[lo:hi])) != "N")\n        win = min(len(good), 8)\n        passes = np.convolve(good.astype(int), np.ones(win, dtype=int), "valid") >= min(3, win)\n        supported = good & (np.convolve(passes.astype(int), np.ones(win, dtype=int)) > 0)\n        indices = np.flatnonzero(supported)\n        if not len(indices):\n            return left, right, (lo, lo)\n        start = lo + max(0, int(indices[0]) - 6)\n        end = lo + int(indices[-1]) + 1\n        if left and int(indices[0]) <= 6:\n            start = lo\n        if right and read.q[hi-1] >= MIN_SINGLE_Q:\n            end = hi\n    return left, right, (start, end)\n\ndef base_probs(read, peak_weight):\n    output = np.tile(0.25, (len(read.seq), 4))\n    for i, call in enumerate(read.seq):\n        if call == "N":\n            continue\n        b = BASES.index(call)\n        error = min(0.75, 10 ** (-min(int(read.q[i]), 35) / 10))\n        other = np.arange(4) != b\n        signal = (np.maximum(read.trace[:,read.peaks[i]], 0) + 1) ** 0.7\n        signal = np.where(other, signal, 0)\n        output[i] = error * ((1-peak_weight)*other/3 + peak_weight*signal/signal.sum())\n        output[i,b] = 1 - error\n    return output\n\ndef overlap_paths(scores, left, right, gap=-3.0):\n    """Best traceback per endpoint. The left prefix and the right suffix are free."""\n    n, m = scores.shape\n    value = np.full((n+1, m+1), -np.inf)\n    move = np.zeros((n+1, m+1), dtype=np.int8)\n    value[:,0] = 0\n    for i in range(1,n+1):\n        for j in range(1,m+1):\n            moves = (value[i-1,j-1]+scores[i-1,j-1], value[i-1,j]+gap, value[i,j-1]+gap)\n            k = max(range(3), key=moves.__getitem__)\n            move[i,j], value[i,j] = k, moves[k]\n    ends = [(n,j) for j in range(1,m+1)] + [(i,m) for i in range(1,n)]\n    for i_end,j_end in sorted(ends, key=lambda ij: value[ij], reverse=True):\n        if value[i_end,j_end] <= 0:\n            break\n        i,j = i_end,j_end\n        mid = []\n        while i and j:\n            k = move[i,j]\n            mid.append((left[i-1] if k!=2 else None, right[j-1] if k!=1 else None))\n            i -= k!=2\n            j -= k!=1\n        if j or not mid or any(None in end for end in (mid[0], mid[-1])):\n            continue\n        prefix = [(ii, None) for ii in left[:i]]\n        tail = [(ii, None) for ii in left[i_end:]] + [(None,jj) for jj in right[j_end:]]\n        yield tuple(prefix + mid[::-1] + tail)\n\ndef make_alignment(cols, reads, matrices, bounds):\n    doubly = [k for k,(i,j) in enumerate(cols) if i is not None and j is not None]\n    pairs = [cols[k] for k in doubly]\n    informative = [(i,j) for i,j in pairs if reads[0].seq[i] in BASES and reads[1].seq[j] in BASES]\n    matches = sum(reads[0].seq[i] == reads[1].seq[j] for i,j in informative)\n    gaps = (doubly[-1]-doubly[0]+1-len(pairs)) if pairs else 0\n    quality_supported = sum(max(reads[0].q[i],reads[1].q[j])>=MIN_SINGLE_Q for i,j in informative)\n    both_q20 = sum(min(reads[0].q[i],reads[1].q[j])>=20 for i,j in informative)\n    metrics = {\n        "overlap_nt": len(pairs),\n        "overlap_matches": matches,\n        "overlap_mismatches": len(informative)-matches,\n        "overlap_unknown": len(pairs)-len(informative),\n        "overlap_gap_nt": gaps,\n        "overlap_identity_pct": 100*matches/(len(pairs)+gaps) if pairs else np.nan,\n        "overlap_any_Q20": sum(max(reads[0].q[i],reads[1].q[j])>=20 for i,j in informative),\n        "overlap_both_Q20": both_q20,\n    }\n    for j,read in enumerate(reads):\n        window = [cols[k][j] for k in doubly]\n        metrics[f"{read.role}_overlap"] = f"{window[0]+1}–{window[-1]+1}" if window else ""\n    first,last = cols[0],cols[-1]\n    has_left = any(bounds[j][0] and first[j]==bounds[j][0][1] for j in range(2) if first[j] is not None)\n    has_right = any(bounds[j][1] and last[j]==bounds[j][1][0]-1 for j in range(2) if last[j] is not None)\n    for name,matrix in matrices.items():\n        if pairs:\n            score = float(sum(matrix[i,j] for i,j in pairs)) - 3*gaps\n        else:\n            # Used only to rank separate single-read sequences in the fallback.\n            score = float(sum(reads[j].q[i]>=20 and reads[j].seq[i]!="N"\n                              for col in cols for j,i in enumerate(col) if i is not None))\n        metrics[f"overlap_{name}_score"] = score if pairs else np.nan\n        metrics[f"base_{name}_score"] = score\n    return {"cols":cols, "metrics":metrics, "left_anchor":has_left, "right_anchor":has_right,\n            "informative":len(informative), "quality_supported":quality_supported}\n\ndef select_alignments(reads, probabilities, boundaries, windows):\n    matrices = {name:np.log(np.maximum(4*a@b.T,1e-12)) for name,(a,b) in probabilities.items()}\n    first,second = [list(range(*window)) for window in windows]\n    best_by_order = {}\n    found = {}\n    for method,matrix in matrices.items():\n        for order in ("ORrc → OF","OF → ORrc"):\n            switch = order.startswith("ORrc")\n            region = matrix[np.ix_(first,second)]\n            left,right,score = (second,first,region.T) if switch else (first,second,region)\n            paths = overlap_paths(score,left,right) if left and right else []\n            for cols in paths:\n                step = tuple((j,i) for i,j in cols) if switch else cols\n                record = make_alignment(step,reads,matrices,boundaries)\n                m = record["metrics"]\n                tag = (order,method)\n                score_name = f"base_{method}_score"\n                best_by_order[tag] = max(best_by_order.get(tag,0),m[score_name])\n                if record["informative"] < MIN_PAIRED_NT:\n                    continue\n                if m["overlap_identity_pct"] < 100*MIN_OVERLAP_IDENTITY:\n                    continue\n                if m["overlap_matches"] < MIN_PAIRED_NT-2 or record["quality_supported"] < MIN_PAIRED_NT-2:\n                    continue\n                if m["overlap_trace_score"] <= 0 or m["overlap_phred_score"] <= 0:\n                    continue\n                if step not in found:\n                    found[step] = dict(record, order=order)\n    supported = sorted(found.values(), key=lambda a: -a["metrics"]["overlap_trace_score"])\n    if supported:\n        best = supported[0]["metrics"]["overlap_trace_score"]\n        supported = [a for a in supported if a["metrics"]["overlap_trace_score"] >= best-ALIGNMENT_SCORE_WINDOW]\n        supported = supported[:MAX_ALIGNMENTS]\n    else:\n        for j, window in enumerate(windows):\n            cols = tuple((i,None) if j==0 else (None,i) for i in range(*window))\n            if cols:\n                supported.append(dict(make_alignment(cols,reads,matrices,boundaries),\n                                      order=f"{reads[j].role} riêng"))\n    for j,a in enumerate(supported,1):\n        a["alignment_id"] = f"A{j:02d}"\n    diagnostics = pd.DataFrame([\n        {"order":order, "model":method, "best_raw_overlap_score":round(float(best_by_order.get((order,method),0)),3)}\n        for order in ("ORrc → OF","OF → ORrc") for method in matrices\n    ])\n    return supported,diagnostics\n\ndef near_peak_alternatives(read):\n    alternatives = []\n    local_maxima = [find_peaks(channel, prominence=45)[0] for channel in read.trace]\n    for i, call in enumerate(read.seq):\n        peaks = read.peaks\n        p = peaks[i]\n        spacings = np.diff(peaks[max(0,i-1):i+2])\n        band = int(np.clip(np.median(spacings)*0.35 if len(spacings) else 3,2,5))\n        primary = np.max(read.trace[BASES.index(call),max(0,p-band):p+band+1]) if call in BASES else 0\n        options = set()\n        if primary > 0 and read.q[i] <= 25:\n            for j,b in enumerate(BASES):\n                if b == call:\n                    continue\n                nearby = local_maxima[j][abs(local_maxima[j]-p)<=band]\n                if len(nearby) and np.max(read.trace[j,nearby]) >= PEAK_RATIO*primary:\n                    options.add(b)\n        alternatives.append(options)\n    return alternatives\n\ndef column_models(cols, reads, probabilities, alternatives):\n    records = []\n    for col in cols:\n        evidence = [(j,i) for j,i in enumerate(col) if i is not None and reads[j].seq[i] in BASES]\n        calls = [reads[j].seq[i] for j,i in evidence]\n        values = [int(reads[j].q[i]) for j,i in evidence]\n        mask = not values or (max(values)<MIN_SINGLE_Q and (len(calls)<2 or calls[0]!=calls[1]))\n        row = {}\n        for method, matrices in probabilities.items():\n            post = np.prod([matrices[j][i] for j,i in evidence],axis=0) if evidence else np.full(4,0.25)\n            post = post/post.sum()\n            options = set(calls)\n            if method == "trace":\n                options.update(b for j,i in evidence for b in alternatives[j][i])\n            top = max(options,key=lambda b:(post[BASES.index(b)],-BASES.index(b))) if options else None\n            if mask:\n                options = {"N"}\n            else:\n                base_score = math.log(post[BASES.index(top)])\n                options = {b for b in options if math.log(post[BASES.index(b)]) >= base_score-MAX_ALT_LOG_DROP}\n            row[method] = (post,options)\n        records.append(row)\n    return records\n\ndef top_sequences(records, method):\n    """Exact top K within the allowed alphabet and change-count budget for this alignment."""\n    bins = {0:[(0.0,"")]}\n    for row in records:\n        post,allowed = row[method]\n        choices = [(0.0,"N")] if allowed=={"N"} else sorted(\n            [(math.log(post[BASES.index(b)]),b) for b in allowed],key=lambda x:(-x[0],x[1])\n        )\n        best = choices[0][1]\n        grown = defaultdict(list)\n        for n,items in bins.items():\n            for extra,b in choices:\n                changes = n+int(b!=best)\n                if changes <= MAX_ALT_CHANGES:\n                    grown[changes].extend((score+extra,seq+b) for score,seq in items)\n        bins = {n:sorted(items,key=lambda x:(-x[0],x[1]))[:TOP_K_PER_MODEL] for n,items in grown.items()}\n    return [seq for _,seq in sorted(\n        (p for items in bins.values() for p in items),key=lambda x:(-x[0],x[1])\n    )[:TOP_K_PER_MODEL]]\n\ndef candidate_score(seq,records,method):\n    logs = []\n    prob = []\n    for b,row in zip(seq,records):\n        post,options = row[method]\n        if b=="N":\n            continue\n        p = float(post[BASES.index(b)])\n        best = max(post)\n        logs.append(math.log(p/best))\n        prob.append(p)\n    return sum(logs), float(np.mean(prob)) if prob else np.nan\n\ndef summarize_candidates(alignments,reads,probabilities):\n    alternatives = [near_peak_alternatives(read) for read in reads]\n    combined = {}\n    legend = {"phred":"Phred","trace":"Phred + peak"}\n    for a in alignments:\n        records = column_models(a["cols"],reads,probabilities,alternatives)\n        if all(row["phred"][1]=={"N"} for row in records):\n            continue\n        sources = defaultdict(list)\n        for method in probabilities:\n            for j,seq in enumerate(top_sequences(records,method),1):\n                sources[seq].append(f\'{legend[method]} {a["alignment_id"]} #{j}\')\n        m = a["metrics"]\n        for seq, provenance in sources.items():\n            scores = {key:candidate_score(seq,records,key) for key in probabilities}\n            ab1_score = m["base_trace_score"]+scores["trace"][0]\n            fields = {\n                "sequence_5to3":seq, "length_nt":len(seq), "N_count":seq.count("N"),\n                "called_nt":len(seq)-seq.count("N"),\n                "ab1_score":ab1_score,\n                "phred_score":m["base_phred_score"]+scores["phred"][0],\n                "mean_call_support":scores["trace"][1],\n                "alignment_id":a["alignment_id"], "order":a["order"],\n                "primer5_boundary":a["left_anchor"], "primer3_boundary":a["right_anchor"],\n                "single_read_nt":sum(i is None or j is None for i,j in a["cols"]),\n                **{key:value for key,value in m.items() if not key.startswith("base_")},\n            }\n            former = combined.get(seq)\n            if former:\n                all_sources = former["sources"] + provenance\n                all_alignments = former["alignment_sources"] | {a["alignment_id"]}\n                # A candidate spanning both boundaries takes precedence over an identical partial span.\n                span = lambda row: int(row["primer5_boundary"]) + int(row["primer3_boundary"])\n                strength = lambda row: (span(row),row["ab1_score"])\n                fields = fields if strength(fields)>strength(former) else former\n            else:\n                all_sources,all_alignments = provenance,{a["alignment_id"]}\n            combined[seq] = dict(fields,sources=all_sources,alignment_sources=all_alignments)\n    if not combined:\n        return pd.DataFrame()\n    table = pd.DataFrame(combined.values())\n    table["sources"] = table["sources"].map(" | ".join)\n    table["alignment_sources"] = table["alignment_sources"].map(lambda x:", ".join(sorted(x)))\n    table["ab1_score"] = table["ab1_score"].round(6)\n    table["phred_score"] = table["phred_score"].round(6)\n    table["mean_call_support"] = table["mean_call_support"].round(4)\n    table = table.sort_values(["ab1_score","N_count","sequence_5to3"],ascending=[False,True,True]).reset_index(drop=True)\n    table.insert(0,"candidate_id",[f"C{i:03d}" for i in range(1,len(table)+1)])\n    table.insert(1,"ab1_rank",table["ab1_score"].rank(ascending=False,method="min").astype(int))\n    table["ab1_delta"] = (table["ab1_score"]-table["ab1_score"].max()).round(6)\n    table["phred_rank"] = table["phred_score"].rank(ascending=False,method="min").astype(int)\n    table["length_delta_expected"] = table["length_nt"]-EXPECTED_REGION_NT if EXPECTED_REGION_NT else pd.NA\n    return table\n\n# Chạy các bước QC, rà peak và xét từng N. Bảng trích xuất cuối nằm ở ô 3.\nwith contextlib.nullcontext() if VERBOSE_QC else contextlib.redirect_stdout(io.StringIO()):\n    _display = display\n    try:\n        if not VERBOSE_QC:\n            display = lambda *_a, **_k: None\n        df_candidates_ab1 = None\n        df_candidates = None\n        df_baseline_ab1 = None\n        df_peak_rescue_snapshot = None\n        df_N_options = None\n        primer5, primer3 = (re.sub(r"\\s+","",x.upper()) for x in (PRIMER_5,PRIMER_3))\n        if any(len(x)<10 or set(x)-set(BASES) for x in (primer5,primer3)):\n            raise ValueError("Mỗi vùng mồi cần ít nhất 10 ký tự A/C/G/T theo chiều chuẩn 5′→3′.")\n        if not (1<=TOP_K_PER_MODEL<=100 and 1<=MAX_ALIGNMENTS<=10 and 0<=MAX_ALT_CHANGES<=10):\n            raise ValueError("Kiểm tra TOP_K_PER_MODEL, MAX_ALIGNMENTS và MAX_ALT_CHANGES.")\n        if not (MIN_PAIRED_NT>=4 and 0<MIN_OVERLAP_IDENTITY<=1 and MIN_SINGLE_Q>=1 and EXPECTED_REGION_NT>=0):\n            raise ValueError("Kiểm tra ngưỡng overlap, Phred và độ dài dự kiến.")\n\n        of = read_ab1(of_bytes,"OF")\n        orr = read_ab1(or_bytes,"ORrc",reverse=True)\n        reads = (of,orr)\n        trims = [trim_read(read,window,primer5,primer3) for read,window in zip(reads,(OF_WINDOW,OR_RC_WINDOW))]\n        boundaries = [(left,right) for left,right,_ in trims]\n        windows = [w for _,_,w in trims]\n        probabilities = {model:tuple(base_probs(read,weight) for read in reads)\n                         for model,weight in (("phred",0),("trace",PEAK_WEIGHT))}\n\n        def format_primer(hit):\n            return f"{hit[0]+1}–{hit[1]} ({hit[2]} sai khác)" if hit else "—"\n\n        df_reads = pd.DataFrame([\n            {"read":read.role,"raw_nt":len(read.seq),"raw_Q20":int(sum(read.q>=20)),\n             "raw_N":read.seq.count("N"),\n             "primer5_hit":format_primer(left),"primer3_hit":format_primer(right),\n             "analysis_window":f"{a+1}–{b}" if a<b else "—", "window_nt":b-a}\n            for read,(left,right,(a,b)) in zip(reads,trims)\n        ])\n        alignments,df_orders = select_alignments(reads,probabilities,boundaries,windows)\n        df_alignments = pd.DataFrame([\n            {"alignment_id":a["alignment_id"],"order":a["order"],\n             **{key:value for key,value in a["metrics"].items() if not key.startswith("base_")}}\n            for a in alignments\n        ])\n        df_candidates_ab1 = summarize_candidates(alignments,reads,probabilities)\n        ab1_run_primers = (primer5,primer3)\n\n        def show_all(table):\n            with pd.option_context("display.max_rows",None,"display.max_columns",None,"display.max_colwidth",None):\n                display(table)\n\n        display(df_reads)\n        display(df_orders)\n        if df_candidates_ab1.empty:\n            print("Chưa có candidate dùng được. Kiểm tra cửa sổ, primer và chất lượng từng read.")\n        else:\n            if not df_candidates_ab1["overlap_nt"].any():\n                print("Không có overlap đạt ngưỡng. Các hàng bên dưới là đoạn đọc riêng của từng read.")\n            display(df_alignments)\n            best_sequence = df_candidates_ab1.iloc[0]["sequence_5to3"]\n            def difference_from_top(seq):\n                if len(seq)!=len(best_sequence):\n                    return f"Δ độ dài {len(seq)-len(best_sequence):+d} nt"\n                return ", ".join(f"{i}{a}>{b}" for i,(a,b) in enumerate(zip(best_sequence,seq),1) if a!=b)\n            df_candidates_ab1["changes_vs_AB1_top"] = df_candidates_ab1["sequence_5to3"].map(difference_from_top)\n            df_candidates = df_candidates_ab1.copy(deep=True)\n            print(f"{len(df_candidates_ab1)} candidate khác nhau. Giới hạn {TOP_K_PER_MODEL} chuỗi/mô hình/đường căn.")\n            print("ab1_score = điểm overlap Phred + peak − phần giảm điểm tại các base đã gọi so với lựa chọn có điểm cao nhất.")\n            print("phred_score dùng phép chấm tương tự với Phred. Với read riêng, điểm nền là số base đạt Q20. Điểm cao hơn được ưu tiên trong từng mô hình.")\n            show_all(df_candidates_ab1)\n\n        # Cố định bảng này để cả phương pháp Phred và nhánh peak có cùng nguồn.\n        df_baseline_ab1 = df_candidates_ab1.copy(deep=True)\n\n        from itertools import combinations\n\n        # Ngưỡng thăm dò. Các tỷ lệ được tính theo vùng lân cận trên cùng chromatogram.\n        GAP_MIN_RATIO = 1.22  # @param {type:"number"}\n        GAP_MIN_SPLIT = 0.45  # @param {type:"number"}\n        INSERT_MIN_HEIGHT = 0.45  # @param {type:"number"}\n        INSERT_MIN_PROMINENCE = 0.22  # @param {type:"number"}\n        INSERT_MIN_DOMINANCE = 1.05  # @param {type:"number"}\n        N_MIN_DOMINANCE = 1.50  # @param {type:"number"}\n        MAX_RESOLVED_EVENTS = 2  # @param {type:"integer"}\n        RESCUE_TOP_K = 12  # @param {type:"integer"}\n\n        EVENT_COLUMNS = [\n            "event_id", "event_type", "passed", "reason", "seed_candidate", "seed_pos",\n            "insert_after_seed_nt", "base_proposed", "read", "read_pos_left", "read_pos_right",\n            "sample_left", "sample_right", "peak_sample", "gap_samples", "expected_spacing",\n            "gap_ratio", "peak_height", "prominence", "peak_width_samples", "height_ratio",\n            "prominence_ratio", "dominance", "peak_evidence",\n        ]\n        RESCUE_COLUMNS = [\n            "seed_candidate", "rescue_rank", "rescue_score", "rescue_edits",\n            "rescued_N_nt", "proposed_extra_nt", "rescue_event_ids",\n        ]\n\n        def peak_catalogue(read):\n            data = []\n            for base, channel in zip(BASES, read.trace):\n                positions, props = find_peaks(\n                    channel, prominence=(None, None), width=(None, None), wlen=31\n                )\n                data.extend(\n                    dict(base_proposed=base, peak_sample=int(pos), peak_height=float(channel[pos]),\n                         prominence=float(prominence), peak_width_samples=float(width))\n                    for pos, prominence, width in zip(positions, props["prominences"], props["widths"])\n                )\n            return pd.DataFrame(data, columns=[\n                "base_proposed", "peak_sample", "peak_height", "prominence", "peak_width_samples",\n            ])\n\n        def flank_height(read, positions):\n            if not positions:\n                return 1.0\n            return max(1.0, float(np.median(np.max(read.trace[:, read.peaks[positions]], axis=0))))\n\n        def local_spacing(peaks, index, gap=False):\n            left, right = max(0, index - 5), min(len(peaks) - 1, index + 6)\n            steps = [float(peaks[j+1]-peaks[j]) for j in range(left, right)\n                     if j not in ({index} if gap else {index-1, index})]\n            return float(np.median(steps)) if steps else np.nan\n\n        def inspect_insertions(read, catalogue, i, seed_id, seed_pos):\n            p, q = map(int, read.peaks[i:i+2])\n            spacing = local_spacing(read.peaks, i, gap=True)\n            gap = q-p\n            if not np.isfinite(spacing) or gap < GAP_MIN_RATIO*spacing:\n                return []\n            data = dict(event_type="insertion", seed_candidate=seed_id,\n                        insert_after_seed_nt=seed_pos, read=read.role, read_pos_left=i+1,\n                        read_pos_right=i+2, sample_left=p, sample_right=q,\n                        gap_samples=gap, expected_spacing=spacing, gap_ratio=gap/spacing)\n            flank = flank_height(read, [i, i+1])\n            lo, hi = p+GAP_MIN_SPLIT*spacing, q-GAP_MIN_SPLIT*spacing\n            peaks = catalogue[catalogue.peak_sample.between(lo, hi)]\n            inspected = []\n            for peak in peaks.itertuples(index=False):\n                if peak.peak_height<=0:\n                    continue\n                col = BASES.index(peak.base_proposed)\n                others = np.delete(read.trace[:,peak.peak_sample],col)\n                dominance = peak.peak_height/max(1.0,float(np.max(others)))\n                h, prominence = peak.peak_height/flank, peak.prominence/flank\n                accepted = (max(read.q[i:i+2])>=MIN_SINGLE_Q and h>=INSERT_MIN_HEIGHT\n                            and prominence>=INSERT_MIN_PROMINENCE and dominance>=INSERT_MIN_DOMINANCE\n                            and .25*spacing<=peak.peak_width_samples<=1.50*spacing)\n                evidence = (min(1.0,h/.8) + min(1.0,prominence/.50) +\n                            min(1.0,dominance/1.50))/3\n                inspected.append(dict(\n                    data, **peak._asdict(), height_ratio=h, prominence_ratio=prominence,\n                    dominance=dominance, passed=accepted, peak_evidence=evidence,\n                    reason="Peak riêng trong khoảng giãn" if accepted\n                    else "Peak không đạt ngưỡng Q, độ nổi, bề rộng hoặc độ trội",\n                ))\n            if not inspected:\n                return [dict(data, passed=False, reason="Khoảng giãn nhưng chưa có peak tách biệt")]\n            # Show all passing alleles. For a negative gap, keep the strongest event for inspection.\n            passed = [x for x in inspected if x["passed"]]\n            return passed or [max(inspected,key=lambda x:x["peak_evidence"])]\n\n        def inspect_unknown(read, catalogue, i, seed_id, seed_pos):\n            p = int(read.peaks[i])\n            spacing = local_spacing(read.peaks, i)\n            data = dict(event_type="resolve_N", seed_candidate=seed_id, seed_pos=seed_pos,\n                        read=read.role, read_pos_left=i+1, read_pos_right=i+1,\n                        sample_left=p, sample_right=p, expected_spacing=spacing)\n            if i==0 or i+1>=len(read.seq) or not np.isfinite(spacing):\n                return dict(data, passed=False, reason="Thiếu hai peak lân cận")\n            steps = np.diff(read.peaks[i-1:i+2])\n            radius = .40*spacing\n            peaks = catalogue[catalogue.peak_sample.between(p-radius, p+radius)]\n            if peaks.empty:\n                return dict(data, passed=False, reason="Vùng N thiếu peak rõ gần PLOC")\n            peak = peaks.sort_values(["peak_height","prominence"],ascending=False).iloc[0].to_dict()\n            channel = BASES.index(peak["base_proposed"])\n            flank = flank_height(read,[i-1,i+1])\n            interval = slice(max(0,math.ceil(p-radius)),min(read.trace.shape[1],math.floor(p+radius)+1))\n            competing = float(np.max(np.delete(read.trace[:,interval],channel,axis=0)))\n            h, prominence = peak["peak_height"]/flank, peak["prominence"]/flank\n            dominance = peak["peak_height"]/max(1.0,competing)\n            accepted = (h>=.55 and prominence>=.25 and dominance>=N_MIN_DOMINANCE\n                        and .25*spacing<=peak["peak_width_samples"]<=1.50*spacing\n                        and np.all((steps>=.6*spacing)&(steps<=1.4*spacing)))\n            evidence = (min(1.0,h/.8) + min(1.0,prominence/.50) + min(1.0,dominance/2))/3\n            return dict(data,**peak,height_ratio=h,prominence_ratio=prominence,dominance=dominance,\n                        passed=bool(accepted),peak_evidence=evidence,\n                        reason="Kênh trội, đỉnh tách rõ" if accepted\n                        else "Peak cạnh tranh hoặc khoảng cách/bề rộng chưa đạt ngưỡng")\n\n        def scan_rescue_events(seed, alignment, reads):\n            lists = [peak_catalogue(read) for read in reads]\n            events = []\n            cols = alignment["cols"]\n            jointly_covered = [p for p,col in enumerate(cols,1) if all(i is not None for i in col)]\n            for p, col in enumerate(cols,1):\n                if jointly_covered and jointly_covered[0]<=p<=jointly_covered[-1]:\n                    continue\n                observed = [(j,i) for j,i in enumerate(col) if i is not None]\n                if len(observed)!=1:\n                    continue\n                j,i = observed[0]\n                if seed.sequence_5to3[p-1]=="N":\n                    events.append(inspect_unknown(reads[j],lists[j],i,seed.candidate_id,p))\n                if p<len(cols):\n                    nextcol = cols[p]\n                    if nextcol[j]==i+1 and nextcol[1-j] is None:\n                        events.extend(inspect_insertions(reads[j],lists[j],i,seed.candidate_id,p))\n            table = pd.DataFrame(events,columns=EVENT_COLUMNS).drop(columns="event_id")\n            table.insert(0,"event_id",[f"E{i:03d}" for i in range(1,len(table)+1)])\n            return table\n\n        def make_rescue_rows(seed, choices):\n            buckets = {}\n            strong = choices.loc[choices["passed"].eq(True)].sort_values(\n                ["peak_evidence","event_id"],ascending=[False,True]\n            ).head(16)\n            options = list(strong.itertuples(index=False))\n            for n in range(1,min(MAX_RESOLVED_EVENTS,len(options))+1):\n                for selected in combinations(options,n):\n                    slots = [("ins",int(e.insert_after_seed_nt)) if e.event_type=="insertion"\n                             else ("N",int(e.seed_pos)) for e in selected]\n                    distinct_peaks = {(e.read,e.peak_sample) for e in selected}\n                    if len(set(slots))!=len(slots) or len(distinct_peaks)!=len(selected):\n                        continue\n                    edits = dict(zip(slots,[e.base_proposed for e in selected]))\n                    seq = "".join(edits.get(("N",p),b)+edits.get(("ins",p),"")\n                                  for p,b in enumerate(seed.sequence_5to3,1))\n                    score = sum(math.log(max(e.peak_evidence,1e-10))-.35 for e in selected)\n                    old = buckets.get(seq)\n                    if old is not None and old["rescue_score"]>=score:\n                        continue\n                    extra = sum(slot[0]=="ins" for slot in slots)\n                    note = " | ".join(f"{e.event_id}: +{e.base_proposed} sau q{int(e.insert_after_seed_nt)}"\n                                      if e.event_type=="insertion"\n                                      else f"{e.event_id}: q{int(e.seed_pos)}N>{e.base_proposed}"\n                                      for e in selected)\n                    buckets[seq] = dict(sequence_5to3=seq,rescue_score=score,seed_candidate=seed.candidate_id,\n                                        rescue_edits=note,rescue_event_ids=" | ".join(e.event_id for e in selected),\n                                        proposed_extra_nt=extra,rescued_N_nt=n-extra)\n            return sorted(buckets.values(),key=lambda r:(-r["rescue_score"],r["rescue_event_ids"]))[:RESCUE_TOP_K]\n\n        def attach_rescues(baseline, alignments, reads):\n            full = baseline.copy(deep=True)\n            for column in RESCUE_COLUMNS:\n                full[column] = np.nan if column in ["rescue_rank","rescue_score","rescued_N_nt","proposed_extra_nt"] else None\n            if baseline.empty:\n                return full,pd.DataFrame(columns=EVENT_COLUMNS)\n            phred = baseline[baseline.sources.str.contains(r"(?:^| \\| )Phred A\\d+ #",regex=True)]\n            if phred.empty:\n                return full,pd.DataFrame(columns=EVENT_COLUMNS)\n            seed = phred.sort_values(["phred_score","candidate_id"],ascending=[False,True]).iloc[0]\n            geometry = next(a for a in alignments if a["alignment_id"]==seed.alignment_id)\n            events = scan_rescue_events(seed,geometry,reads)\n            additions = []\n            for rank,proposal in enumerate(make_rescue_rows(seed,events),1):\n                seq = proposal["sequence_5to3"]\n                known = full.index[full.sequence_5to3==seq]\n                method = "Peak rescue"\n                base = dict(proposal,rescue_rank=rank)\n                if len(known):\n                    k = known[0]\n                    for col in RESCUE_COLUMNS:\n                        full.at[k,col] = base[col]\n                    full.at[k,"sources"] += f" | {method} #{rank}"\n                    continue\n                row = seed.to_dict()\n                row.update(base,candidate_id=f"R{rank:03d}",N_count=seq.count("N"),\n                           called_nt=len(seq)-seq.count("N"),length_nt=len(seq),\n                           single_read_nt=seed.single_read_nt+base["proposed_extra_nt"],\n                           sources=f"{method} #{rank}",changes_vs_AB1_top=base["rescue_edits"],\n                           length_delta_expected=len(seq)-EXPECTED_REGION_NT if EXPECTED_REGION_NT else pd.NA)\n                for col in ["ab1_score","ab1_rank","ab1_delta","phred_score","phred_rank","mean_call_support"]:\n                    row[col] = np.nan\n                additions.append(row)\n            if additions:\n                full = pd.concat([full,pd.DataFrame(additions).reindex(columns=full.columns)],ignore_index=True)\n            return full,events\n\n        if "df_candidates_ab1" not in globals() or df_candidates_ab1 is None:\n            raise ValueError("Chạy ô tạo candidate AB1 trước.")\n        if not (GAP_MIN_RATIO>1 and 0<GAP_MIN_SPLIT<=.5 and 0<INSERT_MIN_HEIGHT<=1\n                and 0<INSERT_MIN_PROMINENCE<=1 and INSERT_MIN_DOMINANCE>=1 and N_MIN_DOMINANCE>=1):\n            raise ValueError("Kiểm tra ngưỡng khoảng giãn, độ nổi, chiều cao và độ trội.")\n        if not 1<=MAX_RESOLVED_EVENTS<=3 or not 1<=RESCUE_TOP_K<=50:\n            raise ValueError("Kiểm tra giới hạn tổ hợp và số candidate mở rộng.")\n\n        # Snapshot từ ô 4. Rerun ô 5 luôn bắt đầu lại từ cùng một bảng.\n        df_candidates_ab1,df_peak_events = attach_rescues(df_baseline_ab1,alignments,reads)\n        df_candidates = df_candidates_ab1.copy(deep=True)\n        df_rescue_ab1 = df_candidates_ab1[df_candidates_ab1["rescue_rank"].notna()].copy()\n        if df_peak_events.empty:\n            print("Không có vùng một-read khả dụng để kiểm tra.")\n        else:\n            keep = ["event_id","event_type","passed","read","read_pos_left","read_pos_right",\n                    "seed_pos","insert_after_seed_nt","base_proposed","peak_sample","gap_ratio",\n                    "prominence_ratio","dominance","reason"]\n            show_all(df_peak_events[keep].round(3))\n        print(f"{len(df_baseline_ab1)} candidate nền · {len(df_rescue_ab1)} candidate có giả thuyết từ peak "\n              f"· {len(df_candidates_ab1)} chuỗi khác nhau.")\n        if not df_rescue_ab1.empty:\n            show_all(df_rescue_ab1[["candidate_id","seed_candidate","rescue_rank","rescue_score",\n                                   "length_nt","N_count","rescue_edits","sequence_5to3"]].round(4))\n\n        # Bảng nền cho ô 5b, giúp chạy lại ô 5b với bộ lọc khác.\n        df_peak_rescue_snapshot = df_candidates_ab1.copy(deep=True)\n\n        # Để trống để thử trên chuỗi Phred và mọi chuỗi từ nhánh rà peak.\n        N_SEED_IDS = ""  # @param {type:"string"}\n        # Tọa độ trên chuỗi Phred gốc. Ví dụ "44", hoặc "44,56".\n        N_POSITIONS = ""  # @param {type:"string"}\n\n        N_FIELDS = ["n_alt_rank","n_alt_score","n_event_id","n_seed_id",\n                    "n_original_pos","n_candidate_pos","n_base_proposed","n_sources"]\n\n        def trace_options_for_N(read, catalogue, i):\n            spacing = local_spacing(read.peaks,i)\n            if not np.isfinite(spacing):\n                return []\n            x = int(read.peaks[i])\n            radius = .45*spacing\n            # Chặn cửa sổ ở trung điểm cho mỗi base-call bên cạnh.\n            lower = max(x-radius, (x+read.peaks[i-1])/2 if i else 0)\n            upper = min(x+radius, (x+read.peaks[i+1])/2 if i+1<len(read.peaks) else read.trace.shape[1]-1)\n            neighborhood = slice(max(0,math.ceil(lower)),min(read.trace.shape[1],math.floor(upper)+1))\n            signal = read.trace[:,neighborhood]\n            if not signal.size:\n                return []\n            max_height = float(np.max(signal))\n            if max_height<=0:\n                return []\n            flank = flank_height(read,[j for j in (i-1,i+1) if 0<=j<len(read.seq)])\n            near = catalogue[catalogue.peak_sample.between(lower,upper)]\n            options = []\n            for b, channel in zip(BASES, read.trace):\n                peaks = near[near.base_proposed.eq(b)].sort_values(\n                    ["peak_height","prominence"],ascending=False\n                )\n                called = b==read.seq[i]\n                if peaks.empty:\n                    if not called:\n                        continue\n                    height,prominence,at = float(channel[x]),0.,x\n                else:\n                    peak = peaks.iloc[0]\n                    height,prominence,at = peak.peak_height,peak.prominence,int(peak.peak_sample)\n                    if not called and not (.25*spacing<=peak.peak_width_samples<=1.50*spacing\n                                           and prominence>=.15*flank):\n                        continue\n                if height<.60*max_height or height<.30*flank:\n                    continue\n                # Điểm thăm dò cục bộ, chỉ xếp các phương án N. Điểm cao hơn được xem trước.\n                score = .45*height/max_height+.45*min(1.,prominence/(.60*flank))+.10*called\n                options.append(dict(n_base_proposed=b, n_alt_score=score, called_in_AB1=called,\n                                    peak_sample=at, peak_height=height, peak_prominence=prominence,\n                                    relative_height=height/max_height))\n            return sorted(options,key=lambda a:(-a["n_alt_score"],a["n_base_proposed"]))\n\n        def n_alternatives(base_table, events, reads, seed_input="", position_input=""):\n            result = base_table.copy(deep=True)\n            for col in N_FIELDS:\n                result[col] = np.nan if col in {"n_alt_rank","n_alt_score","n_original_pos","n_candidate_pos"} else None\n            if events.empty or base_table.empty:\n                return result,pd.DataFrame()\n            root_id = events.iloc[0].seed_candidate\n            requested = [x.strip().upper() for x in seed_input.split(",") if x.strip()]\n            seed_ids = list(dict.fromkeys(requested if requested else [\n                root_id,*base_table.loc[base_table.rescue_rank.notna(),"candidate_id"].tolist()\n            ]))\n            candidates = base_table.set_index("candidate_id",drop=False)\n            eligible = {root_id,*base_table.loc[base_table.rescue_rank.notna(),"candidate_id"].tolist()}\n            missing = set(seed_ids)-eligible\n            if missing:\n                raise ValueError("N_SEED_IDS phải là candidate Phred gốc hoặc candidate rà peak: "+", ".join(sorted(missing)))\n            positions = {int(x.strip()) for x in position_input.split(",") if x.strip()}\n            if positions-set(range(1,int(candidates.at[root_id,"length_nt"])+1)):\n                raise ValueError("N_POSITIONS phải là vị trí hợp lệ trên chuỗi Phred gốc.")\n\n            unresolved = events.loc[events.event_type.eq("resolve_N") & events.passed.eq(False)]\n            if positions:\n                unresolved = unresolved[unresolved.seed_pos.isin(positions)]\n            audits,proposals = [],[]\n            read_map = {r.role:r for r in reads}\n            catalogues = {role:peak_catalogue(r) for role,r in read_map.items()}\n            event_map = events.set_index("event_id")\n            for event in unresolved.itertuples(index=False):\n                old = int(event.seed_pos)\n                read = read_map[event.read]\n                call_index = int(event.read_pos_left)-1\n                options = trace_options_for_N(read,catalogues[event.read],call_index)\n                audits.extend(dict(n_event_id=event.event_id,n_original_pos=old,read=event.read,\n                                   read_pos=call_index+1,basecall=read.seq[call_index],\n                                   phred=int(read.q[call_index]),**option) for option in options)\n                for seed_id in seed_ids:\n                    seed = candidates.loc[seed_id]\n                    event_ids = str(seed.get("rescue_event_ids") or "").split(" | ")\n                    insertions = event_map.loc[event_map.index.isin(event_ids)]\n                    offset = int((insertions.event_type.eq("insertion") &\n                                  insertions.insert_after_seed_nt.lt(old)).sum())\n                    pos = old+offset\n                    seq = seed.sequence_5to3\n                    if seq[pos-1]!="N":\n                        continue\n                    for opt in options:\n                        letter = opt["n_base_proposed"]\n                        updated = seq[:pos-1]+letter+seq[pos:]\n                        row = seed.to_dict()\n                        row.update(sequence_5to3=updated,N_count=updated.count("N"),\n                                   called_nt=len(updated)-updated.count("N"),n_event_id=event.event_id,\n                                   n_seed_id=seed_id,n_original_pos=old,n_candidate_pos=pos,\n                                   n_base_proposed=letter,n_alt_score=opt["n_alt_score"],\n                                   n_sources=f"{seed_id} q{pos} N>{letter} ({event.event_id})")\n                        for col in ("ab1_rank","ab1_score","ab1_delta","phred_rank","phred_score",\n                                    "mean_call_support","rescue_rank","rescue_score"):\n                            row[col] = np.nan\n                        row["changes_vs_AB1_top"] = row["n_sources"]\n                        proposals.append(row)\n\n            # Một chuỗi chỉ xuất hiện một lần, có thể đến từ nhiều chuỗi nền.\n            found = {}\n            for row in sorted(proposals,key=lambda v:(-v["n_alt_score"],v["n_original_pos"],v["n_seed_id"],v["n_base_proposed"])):\n                known = found.get(row["sequence_5to3"])\n                if known is None:\n                    found[row["sequence_5to3"]] = row\n                else:\n                    known["n_sources"] += " | "+row["n_sources"]\n            added = []\n            sequences = {seq:i for i,seq in result.sequence_5to3.items()}\n            rank,previous = 0,None\n            for order,row in enumerate(found.values(),1):\n                score = round(row["n_alt_score"],6)\n                if score!=previous:\n                    rank,previous = order,score\n                row.update(n_alt_rank=rank,n_alt_score=score)\n                seq = row["sequence_5to3"]\n                if seq in sequences:\n                    k = sequences[seq]\n                    for col in N_FIELDS:\n                        result.at[k,col] = row[col]\n                    result.at[k,"sources"] += f" | N alternatives #{rank}"\n                else:\n                    row.update(candidate_id=f"N{len(added)+1:03d}",sources=f"N alternatives #{rank}")\n                    added.append(row)\n            if added:\n                result = pd.concat([result,pd.DataFrame(added).reindex(columns=result.columns)],ignore_index=True)\n            return result,pd.DataFrame(audits)\n\n        if "df_peak_rescue_snapshot" not in globals():\n            raise ValueError("Chạy ô 5 trước.")\n        df_candidates_ab1,df_N_options = n_alternatives(\n            df_peak_rescue_snapshot,df_peak_events,reads,N_SEED_IDS,N_POSITIONS\n        )\n        df_candidates = df_candidates_ab1.copy(deep=True)\n        df_N_candidates = df_candidates_ab1[df_candidates_ab1["n_alt_rank"].notna()].copy()\n        print(f"{len(df_N_candidates)} chuỗi có phương án thay từng N · {len(df_candidates_ab1)} chuỗi khác nhau.")\n        if not df_N_options.empty:\n            show_all(df_N_options.round(3))\n        if not df_N_candidates.empty:\n            show_all(df_N_candidates[["candidate_id","n_alt_rank","n_alt_score","n_seed_id",\n                                     "n_candidate_pos","n_base_proposed","N_count","n_sources","sequence_5to3"]])\n    finally:\n        display = _display\n'

CELL3_SOURCE = '# @title 3 · Chốt danh sách candidate và chỉ số hỗ trợ\nFINAL_COMBINED_PER_SEED = 4  # @param {type:"integer"}\ndf_final_ref = None\ndf_all_reference = None\nif not 1 <= FINAL_COMBINED_PER_SEED <= 30:\n    raise ValueError("Giới hạn tổ hợp phải nằm trong 1–30.")\n\ndef combined_n_candidates(table, n_options):\n    if table.empty or n_options.empty:\n        return pd.DataFrame()\n    singles = table.loc[table["n_seed_id"].notna()]\n    seeds = table.set_index("candidate_id",drop=False)\n    source_options = n_options.drop_duplicates(["n_event_id","n_base_proposed"]).set_index(\n        ["n_event_id","n_base_proposed"]\n    )["n_alt_score"].to_dict()\n    known = set(table.sequence_5to3)\n    found = []\n    for seed_id, group in singles.groupby("n_seed_id",sort=True):\n        seed = seeds.loc[seed_id]\n        by_position = defaultdict(dict)\n        for row in group.itertuples(index=False):\n            key = (row.n_event_id,row.n_base_proposed)\n            if key in source_options:\n                by_position[int(row.n_candidate_pos)][row.n_base_proposed] = source_options[key]\n        if len(by_position)<2:\n            continue\n        # Top K exact theo tổng log điểm cục bộ, trong tập có một lựa chọn trên từng vị trí đủ dữ liệu.\n        top = [(0.,())]\n        for p, options in sorted(by_position.items()):\n            expanded = [(score+math.log(weight),edits+((p,base),))\n                        for score,edits in top for base,weight in options.items()]\n            top = sorted(expanded,key=lambda v:(-v[0],v[1]))[:FINAL_COMBINED_PER_SEED]\n        for k,(score,changes) in enumerate(top,1):\n            seq = list(seed.sequence_5to3)\n            for p,base in changes:\n                assert seq[p-1]=="N"\n                seq[p-1] = base\n            seq = "".join(seq)\n            if seq in known:\n                continue\n            known.add(seq)\n            row = seed.to_dict()\n            row.update(\n                candidate_id=f"M{len(found)+1:03d}",sequence_5to3=seq,length_nt=len(seq),\n                called_nt=len(seq)-seq.count("N"),N_count=seq.count("N"),\n                sources=f"Combined N {seed_id} #{k}",combination_seed=seed_id,\n                combination_rank=k,combination_score=score,\n                combination_edits=", ".join(f"q{p}N>{b}" for p,b in changes),\n            )\n            for field in ("ab1_rank","ab1_score","ab1_delta","phred_score","phred_rank",\n                          "mean_call_support","rescue_rank","rescue_score","n_alt_rank","n_alt_score"):\n                row[field] = np.nan\n            found.append(row)\n    return pd.DataFrame(found)\n\ndef candidate_support(row, reads, geometry_by_id, by_event):\n    cols = geometry_by_id[row.alignment_id]["cols"]\n    event_ids = row.get("rescue_event_ids")\n    events = by_event[by_event.index.isin(str(event_ids).split(" | "))]\n    extra_after = events.loc[events.event_type.eq("insertion"),"insert_after_seed_nt"].astype(int).tolist()\n    placed = []\n    for q, col in enumerate(cols,1):\n        placed.append(col)\n        placed.extend([(None,None)] * extra_after.count(q))\n    assert len(placed)==len(row.sequence_5to3), f"Coverage mapping mismatch for {row.candidate_id}"\n    q20 = two = q20_conflict = weak = 0\n    for b,col in zip(row.sequence_5to3,placed):\n        if b=="N":\n            continue\n        observed = [(reads[j].seq[i],int(reads[j].q[i])) for j,i in enumerate(col) if i is not None]\n        conflicting = any(base in BASES and base!=b and q>=20 for base,q in observed)\n        q20 += not conflicting and any(base==b and q>=20 for base,q in observed)\n        two += len(observed)==2 and all(base==b for base,q in observed)\n        q20_conflict += conflicting\n        weak += conflicting or not any(base==b and q>=10 for base,q in observed)\n    nt = len(row.sequence_5to3)\n    return dict(q20_supported_nt=q20,q20_support_pct=round(100*q20/nt,2),\n                both_reads_agree_nt=two,q20_conflict_nt=q20_conflict,\n                weak_or_peak_only_nt=weak,called_pct=round(100*(nt-row.N_count)/nt,2))\n\ndef make_final_list(table, combinations, reads, alignments, events):\n    if table.empty:\n        return pd.DataFrame(),pd.DataFrame()\n    full = pd.concat([table,combinations],ignore_index=True) if not combinations.empty else table.copy()\n    events_by_id = events.set_index("event_id")\n    geometry_by_id = {g["alignment_id"]:g for g in alignments}\n    support = pd.DataFrame([candidate_support(row,reads,geometry_by_id,events_by_id)\n                            for _,row in full.iterrows()])\n    full = pd.concat([full.reset_index(drop=True),support],axis=1)\n\n    chosen = []\n    def choose(rows, role, limit, evidence):\n        already = {v["candidate_id"] for v in chosen}\n        for _,row in rows.loc[~rows.candidate_id.isin(already)].head(limit).iterrows():\n            item = row.to_dict()\n            item.update(role=role,decision=evidence(row))\n            chosen.append(item)\n\n    phred = full.loc[full.sources.str.contains(r"(?:^| \\| )Phred A\\d+ #")]\n    phred = phred.sort_values(["phred_score","candidate_id"],ascending=[False,True])\n    choose(phred,"Phred consensus",1,lambda r:"Highest Phred score")\n    choose(phred,"Phred alternative",1,lambda r:r.changes_vs_AB1_top)\n    trace = full.loc[full.sources.str.contains(r"(?:^| \\| )Phred \\+ peak A\\d+ #")]\n    trace = trace.sort_values(["ab1_score","candidate_id"],ascending=[False,True])\n    choose(trace,"Peak substitution",1,lambda r:r.changes_vs_AB1_top)\n    rescued = full.loc[full.rescue_rank.notna()].sort_values("rescue_rank")\n    choose(rescued,"Peak rescue",3,lambda r:r.rescue_edits)\n    if not combinations.empty:\n        # Ưu tiên tổ hợp ở nền có nhiều chỉnh sửa đã qua ngưỡng peak nhất, theo AB1.\n        parents = full.loc[full.candidate_id.isin(combinations.combination_seed)].copy()\n        parents["strict_peak_edits"] = parents.rescued_N_nt.fillna(0)+parents.proposed_extra_nt.fillna(0)\n        parent = parents.sort_values(["strict_peak_edits","rescue_rank","candidate_id"],\n                                     ascending=[False,True,True]).iloc[0].candidate_id\n        combos = full.loc[full.combination_seed.eq(parent)].sort_values("combination_rank")\n        choose(combos,"Combined N hypothesis",FINAL_COMBINED_PER_SEED,\n               lambda r:f"{r.combination_seed}: {r.combination_edits}")\n    report = pd.DataFrame(chosen)\n    report.insert(0,"report_order",np.arange(1,len(report)+1))\n    return report,full\n\ndf_combinations_ab1 = combined_n_candidates(df_candidates_ab1,df_N_options)\ndf_final,df_all_candidates = make_final_list(\n    df_candidates_ab1,df_combinations_ab1,reads,alignments,df_peak_events\n)\nREPORT_FIELDS = ["report_order","candidate_id","role","sequence_5to3","length_nt","N_count",\n                 "q20_supported_nt","q20_support_pct","both_reads_agree_nt",\n                 "weak_or_peak_only_nt","q20_conflict_nt","decision"]\nif df_final.empty:\n    print("Chưa có candidate. Xem bảng chất lượng và vùng cắt ở ô 2.")\nelse:\n    if df_final.overlap_nt.gt(0).any():\n        greatest = df_final.loc[df_final.overlap_nt.idxmax()]\n        print(f"{greatest[\'order\']} · overlap {int(greatest.overlap_nt)} nt · "\n              f"{int(greatest.overlap_matches)} matches · {int(greatest.overlap_gap_nt)} gaps")\n    else:\n        print("Không có overlap đạt ngưỡng. Bảng chỉ chứa candidate từ các đoạn read riêng.")\n    print(f"{len(df_final)} reported candidates · {len(df_all_candidates)} unique sequences generated")\n    show_all(df_final[REPORT_FIELDS])\n'

CELL4_SOURCE = '# @title 4 · Đánh giá với reference, nếu có\nREFERENCE_5_TO_3 = ""  # @param {type:"string"}\nREFERENCE_MODE = "auto_primers"  # @param ["auto_primers","already_between_primers","manual_coordinates"]\nREF_START = 0  # @param {type:"integer"}\nREF_END = 0  # @param {type:"integer"}\n\ndef reference_region(text,mode,start,end,primers):\n    lines = [line.strip() for line in text.splitlines() if line.strip()]\n    if sum(line.startswith(">") for line in lines)>1:\n        raise ValueError("Chỉ nhập một strand reference trong một lần đối chiếu.")\n    full = re.sub(r"\\s+","", "".join(line for line in lines if not line.startswith(">"))).upper()\n    if not full or set(full)-set(BASES):\n        raise ValueError("Reference cần chuỗi A/C/G/T theo chiều 5′→3′ hoặc một bản ghi FASTA.")\n    if mode=="manual_coordinates":\n        if not 1<=start<=end<=len(full):\n            raise ValueError("REF_START và REF_END cần là tọa độ 1-based, tính cả hai đầu.")\n        return full,start-1,end\n    if mode=="already_between_primers":\n        return full,0,len(full)\n    p5,p3 = primers\n    hits5 = [m.start() for m in re.finditer(f"(?={p5})",full)]\n    hits3 = [m.start() for m in re.finditer(f"(?={p3})",full)]\n    intervals = [(i+len(p5),j) for i in hits5 for j in hits3 if i+len(p5)<j]\n    if len(intervals)!=1:\n        raise ValueError(f"Tìm được {len(intervals)} vùng giữa hai motif reference. "\n                         "Dùng manual_coordinates nếu biết biên hoặc already_between_primers nếu bạn dán đúng vùng.")\n    lo,hi = intervals[0]\n    return full,lo,hi\n\ndef align_to_reference(ref,query,left_anchor,right_anchor):\n    """Fit the entire candidate. Reference end overhangs are free for an unobserved boundary."""\n    n,m = len(ref),len(query)\n    s = np.zeros((n+1,m+1),dtype=np.int32)\n    count = np.ones(s.shape,dtype=np.int8)\n    step = np.zeros(s.shape,dtype=np.int8)\n    s[0,:] = -4*np.arange(m+1)\n    s[:,0] = -4*np.arange(n+1) if left_anchor else 0\n    for i,x in enumerate(ref,1):\n        for j,y in enumerate(query,1):\n            diag = 3 if x==y else (0 if y=="N" else -3)\n            opts = (s[i-1,j-1]+diag,s[i-1,j]-4,s[i,j-1]-4)\n            score = max(opts)\n            k = opts.index(score)\n            s[i,j],step[i,j] = score,k\n            sources = (count[i-1,j-1],count[i-1,j],count[i,j-1])\n            count[i,j] = min(2,sum(int(v) for value,v in zip(opts,sources) if value==score))\n    best_end_score = int(np.max(s[:,m]))\n    ends = [n] if right_anchor else np.flatnonzero(s[:,m]==best_end_score).tolist()\n    i,j = ends[-1],m\n    suffix = n-i\n    ambiguous = len(ends)>1 or count[i,j]>1\n    pairs = []\n    while i and j:\n        k = step[i,j]\n        pairs.append((i if k!=2 else None,j if k!=1 else None))\n        i -= k!=2\n        j -= k!=1\n    while j:\n        pairs.append((None,j))\n        j -= 1\n    if left_anchor:\n        while i:\n            pairs.append((i,None))\n            i -= 1\n    return pairs[::-1],i,suffix,bool(ambiguous)\n\ndef compare_one(row,ref,offset):\n    query = row.sequence_5to3\n    aligned,prefix,suffix,tied = align_to_reference(ref,query,row.primer5_boundary,row.primer3_boundary)\n    matches,n_unknown = 0,0\n    subst,ins,deleted,unknown = [],[],[],[]\n    last_ref = offset+prefix\n    for rp,qp in aligned:\n        if rp is not None:\n            last_ref = offset+rp\n        if rp is None:\n            ins.append(f"sau ref{last_ref}:q{qp}{query[qp-1]}")\n        elif qp is None:\n            deleted.append(f"ref{last_ref}{ref[rp-1]}")\n        elif query[qp-1]=="N":\n            n_unknown += 1\n            unknown.append(f"ref{last_ref}/q{qp}")\n        elif ref[rp-1]==query[qp-1]:\n            matches += 1\n        else:\n            subst.append(f"ref{last_ref}{ref[rp-1]}>{query[qp-1]}(q{qp})")\n    n_sub,n_ins,n_del = map(len,(subst,ins,deleted))\n    assessed = matches+n_sub+n_ins+n_del\n    paired = matches+n_sub+n_unknown\n    return {\n        "ref_match_nt":matches,\n        "ref_identity_called_pct":round(100*matches/assessed,2) if assessed else np.nan,\n        "ref_match_pct_full_region":round(100*matches/len(ref),2),\n        "ref_paired_coverage_pct":round(100*paired/len(ref),2),\n        "ref_called_coverage_pct":round(100*(matches+n_sub)/len(ref),2),\n        "ref_sub_nt":n_sub, "ref_ins_nt":n_ins, "ref_del_nt":n_del, "ref_N_paired_nt":n_unknown,\n        "ref_uncovered_end_nt":prefix+suffix,\n        "ref_exact":matches==len(ref)==len(query),\n        "ref_span":f"{offset+prefix+1}–{offset+len(ref)-suffix}" if prefix+suffix<len(ref) else "—",\n        "ref_alignment_tied":tied,\n        "ref_sub_positions":" | ".join(subst), "ref_ins_positions":" | ".join(ins),\n        "ref_del_positions":" | ".join(deleted), "ref_N_positions":" | ".join(unknown),\n    }\n\ndef add_reference_scores(before,ref,offset):\n    extra = pd.DataFrame([compare_one(row,ref,offset) for row in before.itertuples(index=False)])\n    criteria = [\n        (not row.ref_exact,-row.ref_match_nt,row.ref_sub_nt+row.ref_ins_nt+row.ref_del_nt,\n         -row.ref_called_coverage_pct)\n        for row in extra.itertuples(index=False)\n    ]\n    ranks = {key:i for i,key in enumerate(sorted(set(criteria)),1)}\n    extra.insert(0,"ref_rank",[ranks[x] for x in criteria])\n    return pd.concat([before.reset_index(drop=True).copy(deep=True),extra],axis=1)\n\nif "df_final" not in globals() or df_final.empty:\n    raise ValueError("Chạy ô 3 để chốt candidate trước.")\ndf_final_ref = None\ndf_all_reference = None\nif REFERENCE_5_TO_3.strip():\n    full,lo,hi = reference_region(REFERENCE_5_TO_3,REFERENCE_MODE,REF_START,REF_END,ab1_run_primers)\n    df_all_reference = add_reference_scores(df_all_candidates,full[lo:hi],lo)\n    ref_fields = ["candidate_id","ref_rank","ref_match_nt","ref_match_pct_full_region",\n                  "ref_sub_nt","ref_ins_nt","ref_del_nt","ref_N_paired_nt","ref_exact","ref_alignment_tied"]\n    df_final_ref = df_final.merge(df_all_reference[ref_fields],on="candidate_id",\n                                 how="left",validate="one_to_one")\n    print(f"Reference target: {lo+1}–{hi} ({hi-lo} nt). Reference rank is among all generated candidates.")\n    print("Best IDs among all sequences:", ", ".join(df_all_reference.loc[df_all_reference.ref_rank.eq(1),"candidate_id"]))\n    show_all(df_final_ref[REPORT_FIELDS+ref_fields[1:]])\nelse:\n    print("Có thể dán full reference 5′→3′ vào ô này để đối chiếu danh sách đã chốt.")\n'


def run_analysis(of_bytes, or_bytes, *, primer5="ACACGACGCTCTTCCGATCT", primer3="AGATCGGAAGAGCACACGTCT", of_window="", or_rc_window="", expected_region_nt=0, min_paired_nt=10, min_overlap_identity=0.75, min_single_q=10, top_k_per_model=12, max_alignments=3, max_alt_changes=2, reference="", reference_mode="auto_primers", ref_start=0, ref_end=0):
    """Run the notebook pipeline in an isolated namespace and return its tables."""
    import contextlib, io
    env = {"of_bytes": of_bytes, "or_bytes": or_bytes}
    replacements = {
        'PRIMER_5 = "ACACGACGCTCTTCCGATCT"': f"PRIMER_5 = {primer5!r}",
        'PRIMER_3 = "AGATCGGAAGAGCACACGTCT"': f"PRIMER_3 = {primer3!r}",
        'OF_WINDOW = ""': f"OF_WINDOW = {of_window!r}",
        'OR_RC_WINDOW = ""': f"OR_RC_WINDOW = {or_rc_window!r}",
        'EXPECTED_REGION_NT = 0': f"EXPECTED_REGION_NT = {int(expected_region_nt)}",
        'MIN_PAIRED_NT = 10': f"MIN_PAIRED_NT = {int(min_paired_nt)}",
        'MIN_OVERLAP_IDENTITY = 0.75': f"MIN_OVERLAP_IDENTITY = {float(min_overlap_identity)!r}",
        'MIN_SINGLE_Q = 10': f"MIN_SINGLE_Q = {int(min_single_q)}",
        'TOP_K_PER_MODEL = 12': f"TOP_K_PER_MODEL = {int(top_k_per_model)}",
        'MAX_ALIGNMENTS = 3': f"MAX_ALIGNMENTS = {int(max_alignments)}",
        'MAX_ALT_CHANGES = 2': f"MAX_ALT_CHANGES = {int(max_alt_changes)}",
        'REFERENCE_5_TO_3 = ""': f"REFERENCE_5_TO_3 = {reference!r}",
        'REFERENCE_MODE = "auto_primers"': f"REFERENCE_MODE = {reference_mode!r}",
        'REF_START = 0': f"REF_START = {int(ref_start)}",
        'REF_END = 0': f"REF_END = {int(ref_end)}",
    }
    source2 = CELL2_SOURCE
    source4 = CELL4_SOURCE
    for old, new in replacements.items():
        if old in source2: source2 = source2.replace(old, new, 1)
        if old in source4: source4 = source4.replace(old, new, 1)
    log = io.StringIO()
    with contextlib.redirect_stdout(log):
        exec(compile(source2, "sanger_notebook_cell_2", "exec"), env)
        exec(compile(CELL3_SOURCE, "sanger_notebook_cell_3", "exec"), env)
        # Load reference helpers on every run; Module 4 accepts the reference later.
        exec(compile(source4, "sanger_notebook_cell_4", "exec"), env)
    env["pipeline_log"] = log.getvalue()
    return env
